{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2184-03-31 21:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. You're here because of nausea, vomiting, and abdominal pain again. Can you tell me what happened?"
    },
    {
      "turn_number": 2,
      "time": "2184-03-31 21:16:30",
      "speaker": "Patient",
      "text": "Yes, I was feeling okay after my last hospital stay, but the day before yesterday, the nausea came back. Then yesterday afternoon, the pain started—right here in the middle of my stomach."
    },
    {
      "turn_number": 3,
      "time": "2184-03-31 21:17:45",
      "speaker": "Doctor",
      "text": "Was the vomiting like before—small amounts, kind of phlegmy?"
    },
    {
      "turn_number": 4,
      "time": "2184-03-31 21:18:10",
      "speaker": "Patient",
      "text": "Exactly. I couldn’t keep anything down—just sips of tea and a cracker. I tried my lorazepam, even the dissolving tablet, but nothing helped."
    },
    {
      "turn_number": 5,
      "time": "2184-03-31 21:19:00",
      "speaker": "Doctor",
      "text": "I see. You went to the ER earlier today and got some medication there?"
    },
    {
      "turn_number": 6,
      "time": "2184-03-31 21:19:30",
      "speaker": "Patient",
      "text": "Yes, they gave me morphine and Ativan in the IV. That helped a lot. I felt much better, but then the pain and nausea came back this afternoon."
    },
    {
      "turn_number": 7,
      "time": "2184-03-31 21:20:15",
      "speaker": "Doctor",
      "text": "That sounds like one of your typical flares. We’ll keep you on bowel rest for now—no food by mouth—and give you IV fluids and medications to control the nausea."
    },
    {
      "turn_number": 8,
      "time": "2184-03-31 21:21:00",
      "speaker": "Patient",
      "text": "Okay. I’m just glad I’m here. I didn’t want to wait it out again."
    },
    {
      "turn_number": 9,
      "time": "2184-03-31 21:22:00",
      "speaker": "Doctor",
      "text": "We’ve started IV ondansetron, lorazepam, and morphine—same combo that’s worked for you before. We’ll also check your labs to make sure nothing else is going on."
    },
    {
      "turn_number": 10,
      "time": "2184-03-31 21:23:15",
      "speaker": "Patient",
      "text": "Are they checking for infection? I’ve been worried it might be something new."
    },
    {
      "turn_number": 11,
      "time": "2184-03-31 21:24:00",
      "speaker": "Doctor",
      "text": "Yes, we did a chest X-ray to rule out pneumonia—it was clear. Your urine test was normal too. We sent blood cultures to check for infection, but those take a few days."
    },
    {
      "turn_number": 12,
      "time": "2184-03-31 21:25:00",
      "speaker": "Patient",
      "text": "And my stomach? Is it blocked or something?"
    },
    {
      "turn_number": 13,
      "time": "2184-03-31 21:26:00",
      "speaker": "Doctor",
      "text": "Your lipase is normal, so it’s not pancreatitis. Your abdomen is soft, no tenderness—so no signs of obstruction. This looks like your usual gastroparesis flare."
    },
    {
      "turn_number": 14,
      "time": "2184-03-31 21:27:00",
      "speaker": "Patient",
      "text": "That makes sense. It feels just like the last few times."
    },
    {
      "turn_number": 15,
      "time": "2184-03-31 21:28:00",
      "speaker": "Doctor",
      "text": "We also noticed your bicarbonate was low—17—and lactate was slightly high at 2.2. That suggests a mild metabolic acidosis, likely from dehydration and not eating."
    },
    {
      "turn_number": 16,
      "time": "2184-03-31 21:29:15",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 17,
      "time": "2184-03-31 21:30:00",
      "speaker": "Doctor",
      "text": "Not at this level, especially since you’re not running a fever. It should improve as we give you fluids and your stomach starts moving again."
    },
    {
      "turn_number": 18,
      "time": "2184-03-31 21:31:00",
      "speaker": "Patient",
      "text": "Okay, that’s reassuring."
    },
    {
      "turn_number": 19,
      "time": "2184-03-31 21:32:00",
      "speaker": "Doctor",
      "text": "We’ll keep monitoring your labs. For now, rest. We’ll check on you regularly."
    },
    {
      "turn_number": 20,
      "time": "2184-04-01 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling?"
    },
    {
      "turn_number": 21,
      "time": "2184-04-01 08:16:00",
      "speaker": "Patient",
      "text": "Much better. I haven’t felt nauseous since last night. The pain is gone."
    },
    {
      "turn_number": 22,
      "time": "2184-04-01 08:17:00",
      "speaker": "Doctor",
      "text": "That’s great. Your repeat labs show your white count has come down—from 11.2 to 7.2. Your bicarbonate is now 23, and lactate is 1.0. So your acidosis is resolving."
    },
    {
      "turn_number": 23,
      "time": "2184-04-01 08:18:15",
      "speaker": "Patient",
      "text": "So I’m getting better?"
    },
    {
      "turn_number": 24,
      "time": "2184-04-01 08:19:00",
      "speaker": "Doctor",
      "text": "Yes. We’re going to start you on clear liquids—water, broth, apple juice—and see how you tolerate it. If that goes well, we’ll advance to soft foods."
    },
    {
      "turn_number": 25,
      "time": "2184-04-01 08:20:00",
      "speaker": "Patient",
      "text": "Can I have crackers or toast?"
    },
    {
      "turn_number": 26,
      "time": "2184-04-01 08:21:00",
      "speaker": "Doctor",
      "text": "We’ll start with liquids today. If you do well, tomorrow you can have soft solids like toast or oatmeal."
    },
    {
      "turn_number": 27,
      "time": "2184-04-01 08:22:00",
      "speaker": "Patient",
      "text": "And my regular meds? I take levothyroxine at night."
    },
    {
      "turn_number": 28,
      "time": "2184-04-01 08:23:00",
      "speaker": "Doctor",
      "text": "We’ve been giving you your levothyroxine and omeprazole. You can continue those at home as usual."
    },
    {
      "turn_number": 29,
      "time": "2184-04-01 12:50:00",
      "speaker": "Doctor",
      "text": "Just got the update on your blood cultures—they show no growth. So no sign of infection."
    },
    {
      "turn_number": 30,
      "time": "2184-04-01 12:51:00",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried."
    },
    {
      "turn_number": 31,
      "time": "2184-04-01 12:52:00",
      "speaker": "Doctor",
      "text": "Me too. But everything points to this being another flare of your gastroparesis, not a new problem."
    },
    {
      "turn_number": 32,
      "time": "2184-04-01 12:53:00",
      "speaker": "Patient",
      "text": "Will I keep having these flares?"
    },
    {
      "turn_number": 33,
      "time": "2184-04-01 12:54:15",
      "speaker": "Doctor",
      "text": "They can happen, but your GI doctor will help manage them. He’s been notified and wants to see you after discharge."
    },
    {
      "turn_number": 34,
      "time": "2184-04-01 12:55:00",
      "speaker": "Patient",
      "text": "Good. I’ll call his office."
    },
    {
      "turn_number": 35,
      "time": "2184-04-02 09:00:00",
      "speaker": "Doctor",
      "text": "You did well overnight—no nausea, kept down soup and juice. This morning you ate scrambled eggs and toast without issues."
    },
    {
      "turn_number": 36,
      "time": "2184-04-02 09:01:00",
      "speaker": "Patient",
      "text": "I feel almost back to normal."
    },
    {
      "turn_number": 37,
      "time": "2184-04-02 09:02:00",
      "speaker": "Doctor",
      "text": "We’re going to discharge you today. You’ll go home with your usual meds: lorazepam, Tigan, omeprazole, dronabinol, and your thyroid and vitamin D."
    },
    {
      "turn_number": 38,
      "time": "2184-04-02 09:03:00",
      "speaker": "Patient",
      "text": "And if I start feeling sick again?"
    },
    {
      "turn_number": 39,
      "time": "2184-04-02 09:04:00",
      "speaker": "Doctor",
      "text": "Use your PRN meds—Tigan, lorazepam, dronabinol. If symptoms persist, come back or call your GI doctor. And keep following the small-particle diet."
    },
    {
      "turn_number": 40,
      "time": "2184-04-02 09:05:00",
      "speaker": "Patient",
      "text": "I will. Thank you for helping me feel better."
    },
    {
      "turn_number": 41,
      "time": "2184-04-02 09:06:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll let your husband know you’re ready to go home."
    },
    {
      "turn_number": 42,
      "time": "2184-04-02 10:30:00",
      "speaker": "Doctor",
      "text": "Just a final check before discharge. You’re alert, pain-free, and walking fine. Your vitals are stable."
    },
    {
      "turn_number": 43,
      "time": "2184-04-02 10:31:00",
      "speaker": "Patient",
      "text": "I’m ready to go home."
    },
    {
      "turn_number": 44,
      "time": "2184-04-02 10:32:00",
      "speaker": "Doctor",
      "text": "We’ll send the discharge papers and instructions to your email. Follow up with Dr. ___ within a week."
    },
    {
      "turn_number": 45,
      "time": "2184-04-02 10:33:00",
      "speaker": "Patient",
      "text": "I’ll make the appointment today."
    },
    {
      "turn_number": 46,
      "time": "2184-04-02 10:34:00",
      "speaker": "Doctor",
      "text": "Take care. Call if anything changes."
    },
    {
      "turn_number": 47,
      "time": "2184-04-02 11:00:00",
      "speaker": "Patient",
      "text": "One more thing—should I worry about the blood cultures being pending?"
    },
    {
      "turn_number": 48,
      "time": "2184-04-02 11:01:00",
      "speaker": "Doctor",
      "text": "No. They were negative at 24 hours, and you’re improving. It’s very unlikely anything will grow now."
    },
    {
      "turn_number": 49,
      "time": "2184-04-02 11:02:00",
      "speaker": "Patient",
      "text": "Thanks, that helps."
    },
    {
      "turn_number": 50,
      "time": "2184-04-02 11:03:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Just keep up with your follow-up."
    },
    {
      "turn_number": 51,
      "time": "2184-04-02 12:00:00",
      "speaker": "Patient",
      "text": "I packed up. Can I get a wheelchair to the exit?"
    },
    {
      "turn_number": 52,
      "time": "2184-04-02 12:01:00",
      "speaker": "Doctor",
      "text": "Of course. I’ll have someone bring one right over."
    },
    {
      "turn_number": 53,
      "time": "2184-04-02 12:05:00",
      "speaker": "Doctor",
      "text": "Here’s your discharge summary. Your husband has a copy too."
    },
    {
      "turn_number": 54,
      "time": "2184-04-02 12:06:00",
      "speaker": "Patient",
      "text": "Thank you again."
    },
    {
      "turn_number": 55,
      "time": "2184-04-02 12:07:00",
      "speaker": "Doctor",
      "text": "Take care. We’re glad you’re feeling better."
    },
    {
      "turn_number": 56,
      "time": "2184-04-02 12:08:00",
      "speaker": "Patient",
      "text": "I really appreciate it."
    },
    {
      "turn_number": 57,
      "time": "2184-04-02 12:09:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    },
    {
      "turn_number": 58,
      "time": "2184-04-02 12:10:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 59,
      "time": "2184-04-02 12:11:00",
      "speaker": "Doctor",
      "text": "We’ll see you in follow-up."
    },
    {
      "turn_number": 60,
      "time": "2184-04-02 12:12:00",
      "speaker": "Patient",
      "text": "Yes, I’ll call Dr. ___ today."
    }
  ],
  "summary": {
    "admission_start": "2184-03-31 21:15:00",
    "admission_end": "2184-04-02 15:34:00",
    "summary_paragraph": "A woman with a history of gastroparesis, J-tube placement, and Nissen fundoplication was admitted for recurrent nausea, vomiting, and midepigastric pain characteristic of her prior flares. She had recently been discharged after a similar episode but developed symptoms again the day prior to admission. In the ED, she received IV morphine and lorazepam with temporary relief. Labs on admission showed mild leukocytosis, metabolic acidosis with elevated anion gap, and elevated lactate, likely due to dehydration and reduced oral intake. She was managed with bowel rest, IV fluids, and IV antiemetics and analgesics, including ondansetron, lorazepam, prochlorperazine, and morphine. Her symptoms resolved by hospital day 2, she advanced to solid foods, and repeat labs showed normalization of acidosis and lactate. Blood cultures showed no growth. She was discharged home in stable condition with instructions to follow up with her gastroenterologist.",
    "problems": [
      "Gastroparesis",
      "Acidosis",
      "Dyskinesia of esophagus",
      "Esophageal reflux",
      "Unspecified acquired hypothyroidism",
      "Leukocytosis, unspecified",
      "Osteoporosis, unspecified",
      "Anxiety state, unspecified",
      "Personal history of malignant neoplasm of breast",
      "Personal history of other malignant neoplasm of skin",
      "Family history of malignant neoplasm of gastrointestinal tract"
    ]
  }
}
